package com.ceroa.service;

import com.fasterxml.jackson.databind.ObjectMapper;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;
import org.springframework.web.server.ResponseStatusException;
import org.springframework.http.HttpStatus;
import java.net.*;
import java.net.http.*;
import java.time.Duration;
import java.util.Map;

/** Privileged credential stays on the backend. Paths are generated by the backend, never supplied by a model. */
@Component
public class PrivateDocumentStorage {
    private final String url,key,bucket;private final ObjectMapper json;
    private static final org.slf4j.Logger log=org.slf4j.LoggerFactory.getLogger(PrivateDocumentStorage.class);
    private final HttpClient client=HttpClient.newBuilder().version(HttpClient.Version.HTTP_1_1).connectTimeout(Duration.ofSeconds(5)).build();
    public PrivateDocumentStorage(ObjectMapper json,@Value("${ceroa.library.storage-url:}") String url,
        @Value("${ceroa.library.storage-key:}") String key,@Value("${ceroa.library.bucket:financial-documents}") String bucket) {
        this.json=json;this.url=url.replaceAll("/$","");this.key=key;this.bucket=bucket;
    }
    private HttpRequest.Builder request(String path) {
        if(!url.startsWith("https://")||key.isBlank()||!bucket.matches("[a-z0-9-]+"))throw unavailable();
        return HttpRequest.newBuilder(URI.create(url+"/storage/v1/"+path)).timeout(Duration.ofSeconds(25)).header("apikey",key).header("Authorization","Bearer "+key);
    }
    public void put(String path,byte[] bytes,String mime) {
        try {
            ensurePrivate();
            var res=client.send(request("object/"+bucket+"/"+path).header("Content-Type",mime).header("Cache-Control","no-store").header("x-upsert","false").POST(HttpRequest.BodyPublishers.ofByteArray(bytes)).build(),HttpResponse.BodyHandlers.discarding());
            if(res.statusCode()!=200 && res.statusCode()!=201)throw unavailable();
        }catch(InterruptedException e){Thread.currentThread().interrupt();throw unavailable();}catch(Exception e){throw unavailable();}
    }
    public byte[] read(String path) {
        try {
            ensurePrivate();
            var res=client.send(request("object/authenticated/"+bucket+"/"+path).GET().build(),HttpResponse.BodyHandlers.ofInputStream());
            try(var body=res.body()) {if(res.statusCode()!=200)throw unavailable();byte[] bytes=body.readNBytes(DocumentTextExtractor.MAX_BYTES+1);if(bytes.length>DocumentTextExtractor.MAX_BYTES)throw unavailable();return bytes;}
        }catch(InterruptedException e){Thread.currentThread().interrupt();throw unavailable();}catch(Exception e){throw unavailable();}
    }
    public String signed(String path) {
        try {
            ensurePrivate();
            var res=client.send(request("object/sign/"+bucket+"/"+path).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString("{\"expiresIn\":60}")).build(),HttpResponse.BodyHandlers.ofString());
            if(res.statusCode()!=200)throw unavailable();String signed=json.readTree(res.body()).path("signedURL").asText();
            if(!signed.startsWith("/object/sign/"+bucket+"/"+path+"?"))throw unavailable();return url+"/storage/v1"+signed;
        }catch(InterruptedException e){Thread.currentThread().interrupt();throw unavailable();}catch(Exception e){throw unavailable();}
    }
    public void delete(String path) {
        try {
            var res=client.send(request("object/"+bucket).header("Content-Type","application/json").method("DELETE",HttpRequest.BodyPublishers.ofString(json.writeValueAsString(Map.of("prefixes",java.util.List.of(path))))).build(),HttpResponse.BodyHandlers.ofString());
            if(res.statusCode()!=200){log.warn("Storage delete rejected: HTTP {}",res.statusCode());throw unavailable();}
            // Verify actual removal, including an idempotent retry after an earlier deletion.
            var verify=client.send(request("object/authenticated/"+bucket+"/"+path+"?verification="+java.util.UUID.randomUUID()).header("Cache-Control","no-cache").GET().build(),HttpResponse.BodyHandlers.ofString());
            if(verify.statusCode()!=404 && !(verify.statusCode()==400&&json.readTree(verify.body()).path("statusCode").asText().equals("404")))throw unavailable();
        }catch(InterruptedException e){Thread.currentThread().interrupt();throw unavailable();}catch(Exception e){log.warn("Storage deletion could not be confirmed: {}",e.getClass().getSimpleName());throw unavailable();}
    }
    private void ensurePrivate()throws Exception {
        var check=client.send(request("bucket/"+bucket).GET().build(),HttpResponse.BodyHandlers.ofString());
        if(check.statusCode()!=200||!json.readTree(check.body()).path("public").isBoolean()||json.readTree(check.body()).path("public").asBoolean())throw unavailable();
    }
    private ResponseStatusException unavailable(){return new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Almacenamiento privado no disponible");}
}
